{
  "id": 2,
  "knowledge": "Treatment Adherence Rate (TAR)",
  "description": "Measures the proportion of patients with high or medium treatment adherence at a facility.",
  "definition": "TAR = \frac{\text{Number of outcomes with Treatment Adherence of 'High', 'Medium', or 'Compliant'}}{\text{Total number of treatment outcomes}} \text{ for a given facility.}"
}

{
  "id": 4,
  "knowledge": "Therapy Engagement Score (TES)",
  "description": "Computes an average engagement score across therapy sessions.",
  "definition": "TES = \text{The average of engagement scores, where the score is 3 for 'High' engagement, 2 for 'Medium', and 1 for 'Low'.}"
}

{
  "id": 30,
  "knowledge": "Symptom Severity Index (SSI)",
  "description": "Calculates a combined average symptom severity score for a facility, based on depression and anxiety.",
  "definition": "SSI = \frac{\text{Average PHQ-9 Score} + \text{Average GAD-7 Score}}{2}"
}

{
  "id": 3,
  "knowledge": "Suicide Risk Prevalence (SRP)",
  "description": "Calculates the percentage of assessments indicating high or severe suicide risk at a facility.",
  "definition": "SRP = \frac{\text{Number of assessments with a 'High' suicide risk}}{\text{Total number of assessments}} \times 100 \text{ for a given facility.}"
}
